package com.hostelfind.model;
import com.fasterxml.jackson.annotation.JsonIgnore; import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="items") public class Item { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false) private String title; @Column(nullable=false,length=2000) private String description; @Column(nullable=false) private String category; private String imageUrl; @Column(nullable=false) private String location; @Column(nullable=false) private LocalDateTime date; @Enumerated(EnumType.STRING) @Column(nullable=false) private ItemType type; @Enumerated(EnumType.STRING) @Column(nullable=false) private ItemStatus status=ItemStatus.PENDING; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="user_id",nullable=false) private User user; public Long getId(){return id;} public String getTitle(){return title;} public String getDescription(){return description;} public String getCategory(){return category;} public String getImageUrl(){return imageUrl;} public String getLocation(){return location;} public LocalDateTime getDate(){return date;} public ItemType getType(){return type;} public ItemStatus getStatus(){return status;} @JsonIgnore public User getUser(){return user;} public void setTitle(String v){title=v;} public void setDescription(String v){description=v;} public void setCategory(String v){category=v;} public void setImageUrl(String v){imageUrl=v;} public void setLocation(String v){location=v;} public void setDate(LocalDateTime v){date=v;} public void setType(ItemType v){type=v;} public void setStatus(ItemStatus v){status=v;} public void setUser(User v){user=v;} }
